// Variable: SECTIONS_FRAGMENT
// Query: [defined(@->_id)]->{  _id,  _type,    name,  tagline,  heading,  intro,  description,  layout,  sectionLayout,  gridMode,  mobileDisplay,  cardStyle,  hoverEffects,  showArrow,  iconPosition,  mode,  reviewsEmbed,  footerHeading,  footerDescription,  // contentSection (Phase 11): its eyebrow is the shared tagline key above;  // the rest are its own. Flat, like every other key here: a nested select  // would type-check against the flat props while every key read undefined.  headingEmphasis,  mediaSide,  showPhone,  marquee,  imageTreatment,  "body": body []{  _type,  _key,  style,  markDefs,  children,  listItem,  level,  _type == "image" => {    ...,    "alt": coalesce(alt, ""),    caption,    "lqip": asset->metadata.lqip,    "dimensions": asset->metadata.dimensions  },  _type == "officeHours" => {    title  }},  "pullQuote": pullQuote{text, attribution},  "proof": proof{number, caption},  "media": media{    kind,    "image": image {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions},    "video": video->{_id, title, youTubeUrl, description, videoType}  },  // The appearance fieldset. EXPLICIT, not a splat, so every field the schema  // gains must be added HERE too or it never reaches the component. Phase 13's  // three frame fields were built, tested, merged and propagated before anyone  // noticed the query did not carry them: the unit tests pass props directly,  // the golden renders components directly, and the stub fixture sets none of  // them, so nothing in CI could see it. Only the live page did.  // sectionBody.test.ts now asserts the whole key set.  "appearance": {    "surface": surface,    "spacing": spacing,    "inset": inset,    "edgeBottom": edgeBottom,    "overlapPrevious": overlapPrevious,    "backgroundImage": sectionBackgroundImage {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}  },  // practiceAreaNav (silo nav): resolve each item's page reference to an href +  // auto-pulled title/description, with per-item overrides; or auto-list all  // top-level practice areas. href mirrors navItemPracticeAreas ("/" + slug + "/").  "items": select(    _type in ["practiceAreaNav", "practiceAreaNavInline"] && mode == "allTopLevel" => [      ...(*[_type == "mainNavigation"][0].items[_type == "navItemPracticeAreas"][0].practiceAreaOrder[defined(@->slug.current) && !defined(@->parentPage)][defined(@->_id)]->{  "_key": _id,  "label": coalesce(select(navLabel != "" => navLabel), title),  "href": "/" + slug.current + "/",  "description": metaDescription,  "icon": null,  "image": null,  "featured": false}),      ...(*[_type == "practiceArea" && defined(slug.current) && !defined(parentPage) && !(_id in coalesce(*[_type == "mainNavigation"][0].items[_type == "navItemPracticeAreas"][0].practiceAreaOrder[]._ref, []))]{  "_key": _id,  "label": coalesce(select(navLabel != "" => navLabel), title),  "href": "/" + slug.current + "/",  "description": metaDescription,  "icon": null,  "image": null,  "featured": false} | order(label asc))    ],    _type in ["practiceAreaNav", "practiceAreaNavInline"] =>      items[defined(page->slug.current)]{        _key,        "label": coalesce(label, coalesce(select(page->navLabel != "" => page->navLabel), page->title)),        "href": "/" + page->slug.current + "/",        "description": coalesce(description, page->metaDescription),        "icon": icon {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions},        "image": image {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions},        "featured": featured      },    // contentSection's items: a title and a body (on a stat row, the number    // and its caption). Without this branch the select yields null.    _type in ["contentSection", "contentSectionInline"] => items[]{_key, title, body}  ),  "buttons": buttons[]{title, url, variant},  "footerButton": footerButton{title, url, variant},  "ctaButton": ctaButton{title, url, variant},  "image": image {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions},  "testimonials": testimonials[defined(@->_id)]->{  _id, quote, name, caseType, numberOfStars,  "avatar": avatar {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}},  "testimonial": testimonial->{  _id, quote, name, caseType, numberOfStars,  "avatar": avatar {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}},  "questions": questions[defined(@->_id)]->{    question,    "answer": answer []{  _type,  _key,  style,  markDefs,  children,  listItem,  level,  _type == "image" => {    ...,    "alt": coalesce(alt, ""),    caption,    "lqip": asset->metadata.lqip,    "dimensions": asset->metadata.dimensions  },  _type == "officeHours" => {    title  }},    category,    "slug": slug.current,    tags  },  "caseResults": caseResults[defined(@->_id)]->{    _id, amount, caseType, caption, year  },  "badges": badges[defined(@->_id)]->{    "src": image.asset->url,    "alt": image.alt,    "width": image.asset->metadata.dimensions.width,    "height": image.asset->metadata.dimensions.height  },  "orderedAttorneyIds": select(    mode == 'practiceArea' => *[_type == "attorneyIndex"][0].orderedAttorneys[]._ref,    null  ),  // The title key holds the RENDERED nav label, not the stored Name — same  // shape as the sidebar tree, and for the same reason. Ruled 2026-08-07,  // Pass D.2: attorney cards are an index-card surface, which NAME-1 gives the  // Nav Label. Three branches because the block has three modes.  "attorneys": select(    mode == 'all' => *[_type == "attorneyIndex"][0].orderedAttorneys[defined(@->_id)]->{      _id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, h1, jobTitle, "bio": metaDescription,      "photo": photo {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}    },    mode == 'practiceArea' => *[_type == "attorneyPage" && references(^.practiceAreaPage._ref)]{      _id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, h1, jobTitle, "bio": metaDescription,      "photo": photo {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}    },    mode == 'manual' => attorneys[defined(@->_id)]->{      _id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, h1, jobTitle, "bio": metaDescription,      "photo": photo {  ...,  "alt": coalesce(alt, ""),  "lqip": asset->metadata.lqip,  "dimensions": asset->metadata.dimensions}    },    []  ),  "videos": videos[defined(@->_id)]->{    _id, title, youTubeUrl, description, videoType  }}
