    '\n  *[_type == "blogPost"] | order(defined(publishedAt) desc, publishedAt desc) {\n    "slug": slug.current,\n    h1,\n    metaDescription,\n    publishedAt,\n    // Ruled 2026-08-07, Pass D.2. The category chip on a post card is index-card\n    // and link text, which NAME-1 gives the Nav Label. The title key holds the\n    // RENDERED label; consumers filter on the slug, never on this string.\n    "category": category->{\n      "title": coalesce(select(navLabel != "" => navLabel), title),\n      "slug": slug.current\n    },\n    "bodyText": pt::text(body)\n  }\n': BLOG_POSTS_QUERY_RESULT;
