    '\n  *[_type == "blogPost" && slug.current == $slug][0]{\n    "ogImage": ogImageOverride {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n},\n    h1,\n    title,\n    navLabel,\n    "slug": slug.current,\n    seoTitle,\n    metaDescription,\n    ogTitle,\n    ogDescription,\n    noIndex,\n    noFollow,\n    canonicalUrl,\n    publishedAt,\n    lastModified,\n    "featuredImage": featuredImage {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n},\n    "bodyText": pt::text(body),\n    "body": body []{\n  _type,\n  _key,\n  style,\n  markDefs,\n  children,\n  listItem,\n  level,\n  _type == "image" => {\n    ...,\n    "alt": coalesce(alt, ""),\n    caption,\n    "lqip": asset->metadata.lqip,\n    "dimensions": asset->metadata.dimensions\n  },\n  _type == "officeHours" => {\n    title\n  }\n},\n    "authors": authors[defined(@->_id)]->{\n      _id,\n      firstName,\n      lastName,\n      jobTitle,\n      "slug": slug.current,\n      "photo": photo {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n}\n    },\n    // Same chip signature as BLOG_POSTS_QUERY, same 2026-08-07 Pass D.2 ruling.\n    // The blog-post route also hands this object to resolvePageLabel for the\n    // breadcrumb rung; that resolver\'s first rung reads navLabel, which is not\n    // projected here, so it falls to the title key \u2014 the string this expression\n    // has already resolved. Same answer either way, and NOT a second ladder:\n    // the GROQ half answers once and the resolver passes it through.\n    "category": category->{\n      "title": coalesce(select(navLabel != "" => navLabel), title),\n      "slug": slug.current\n    },\n    "sidebar": sidebar[]{\n      _type,\n      _key,\n      _type == "sidebarTableOfContents" => {\n        "_componentType": "sidebarTableOfContents"\n      },\n      _type == "reference" => @->{\n        "_componentType": _type,\n        name,\n        header,\n        description,\n        mode,\n        layout,\n        postCount,\n        "formEmbed": form->formEmbed,\n        tagline,\n        supportingText1,\n        supportingText2,\n        phoneNumber,\n        "button": button{title, url, variant},\n        // WS-Sidebar Phase 2.3 \u2014 see SIDEBAR_FRAGMENT comment block. This\n        // inline projection (blog post page) must stay in sync with the fragment.\n        // (The recentPosts sub-query below now uses the $slug query param; the\n        // earlier ^.^.slug.current parent-reference resolved to null and listed the\n        // current post \u2014 that bug was the practical reason it stayed inline.)\n        "orderedAolIds": *[_type == "mainNavigation"][0]\n          .items[_type == "navItemPracticeAreas"][0]\n          .practiceAreaOrder[]._ref,\n        "areasOfLaw": *[\n          _type == "practiceArea" && !defined(parentPage) && defined(slug.current)\n        ]{\n          _id,\n          "slug": slug.current,\n          "title": coalesce(select(navLabel != "" => navLabel), title),\n          "children": *[\n            _type == "practiceArea" && parentPage._ref == ^._id && defined(slug.current)\n          ]{\n            _id,\n            "slug": slug.current,\n            "title": coalesce(select(navLabel != "" => navLabel), title),\n            "grandchildren": *[\n              _type == "practiceArea" && parentPage._ref == ^._id && defined(slug.current)\n            ]{\n              "slug": slug.current,\n              "title": coalesce(select(navLabel != "" => navLabel), title),\n            } | order(title asc),\n          } | order(title asc),\n        },\n        "orderedAttorneyIds": select(\n          mode == \'practiceArea\' => *[_type == "attorneyIndex"][0].orderedAttorneys[]._ref,\n          null\n        ),\n        "attorneys": select(\n          mode == \'all\' => *[_type == "attorneyIndex"][0].orderedAttorneys[defined(@->_id)]->{_id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, "photo": photo {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n}},\n          mode == \'practiceArea\' => *[_type == "attorneyPage" && references(^.practiceAreaPage._ref)]{_id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, "photo": photo {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n}},\n          attorneys[defined(@->_id)]->{_id, "title": coalesce(select(navLabel != "" => navLabel), title), "slug": slug.current, "photo": photo {\n  ...,\n  "alt": coalesce(alt, ""),\n  "lqip": asset->metadata.lqip,\n  "dimensions": asset->metadata.dimensions\n}}\n        ),\n        "links": links[defined(@->_id)]->{\n          _id,\n          _type,\n          "slug": slug.current,\n          "title": coalesce(select(navLabel != "" => navLabel), title)\n        },\n        "posts": select(\n          mode == "recentPosts" => *[_type == "blogPost" && slug.current != $slug] | order(defined(publishedAt) desc, publishedAt desc)[0..20]{\n            h1,\n            "slug": slug.current\n          },\n          mode == "faqPosts" => *[_type == "blogPostFaq"] | order(defined(publishedAt) desc, publishedAt desc)[0..20]{\n            h1,\n            "slug": slug.current\n          }\n        )\n      }\n    },\n    hideCtaForm,\n    "ctaOverride": ctaFormOverride {\n  tagline,\n  heading,\n  description,\n  "buttons": buttons[]{title, url, variant}\n}\n  }\n': BLOG_POST_PAGE_QUERY_RESULT;
